import {STORAGE,categories,dateKey,parseDate,addDays,weekStart,emptyData,validateData,occurrences,conflicts,dueReminders,demoData,calendarExport} from './model.js';
const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',check:'<path d="m5 12 4 4L19 6"/>',list:'<path d="M9 6h12M9 12h12M9 18h12M3 6h.01M3 12h.01M3 18h.01"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>',plus:'<path d="M12 5v14M5 12h14"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',book:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;
let loadError='',data=emptyData();try{const raw=localStorage.getItem(STORAGE);if(raw)data=validateData(JSON.parse(raw));}catch{loadError='Не удалось прочитать сохранённые данные. Вы можете импортировать резервную копию в настройках. Исходная запись сохранена.';}
let selected=dateKey(),view='today',filter='all',query='',toastTimer,modalReturn=null;
const fmt=(d,options)=>parseDate(d).toLocaleDateString('ru-RU',options);
const pretty=d=>fmt(d,{day:'numeric',month:'long'});
function toast(s){$('#toast').textContent=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',5000);}
function commit(next){try{const clean=validateData(next);if(loadError){const raw=localStorage.getItem(STORAGE);if(raw)localStorage.setItem(STORAGE+':recovery:'+Date.now(),raw);}localStorage.setItem(STORAGE,JSON.stringify(clean));loadError='';data=clean;render();return true;}catch(e){toast('Не удалось сохранить: '+e.message);return false;}}
function update(fn){const next=structuredClone(data);fn(next);return commit(next);}
function tag(c){return `<span class="tag ${c}">${categories[c]}</span>`;}
function weekbar(){const start=weekStart(selected);return `<div class="weekbar"><div class="week-head"><strong>${pretty(start)} · ${pretty(addDays(start,6))}</strong><div class="week-controls"><button data-action="prev" aria-label="Предыдущая неделя">${icon('left')}</button><button data-action="today">Сегодня</button><button data-action="next" aria-label="Следующая неделя">${icon('right')}</button></div></div><div class="week-days">${Array.from({length:7},(_,i)=>{const d=addDays(start,i),count=occurrences(data,d).length+data.tasks.filter(t=>t.date===d&&!t.done).length;return `<button class="day ${d===selected?'active':''} ${d===dateKey()?'today':''}" data-action="date" data-date="${d}" ${d===selected?'aria-current="date"':''} aria-label="${fmt(d,{weekday:'long',day:'numeric',month:'long'})}, записей: ${count}"><span>${fmt(d,{weekday:'short'})}</span><b>${parseDate(d).getDate()}</b><div class="dots">${Array.from({length:Math.min(count,3)},()=>'<i class="dot"></i>').join('')}</div></button>`;}).join('')}</div></div>`;}
function taskCard(t){const overdue=!t.done&&t.date<dateKey();return `<article class="task ${t.done?'done':''}"><button class="check" data-action="toggle-task" data-id="${escape(t.id)}" aria-pressed="${t.done}" aria-label="${t.done?'Вернуть в дела':'Выполнить'}: ${escape(t.title)}"><span>${t.done?icon('check'):''}</span></button><div class="task-body"><button class="task-title" data-action="edit-task" data-id="${escape(t.id)}">${escape(t.title)}</button><div class="task-meta">${tag(t.category)}<span class="${overdue?'late':''}">${overdue?'Просрочено · ':''}${t.date===selected?'':pretty(t.date)+' · '}${t.time||'Без времени'}</span><span>${t.duration} мин</span></div>${t.notes?`<p class="notes">${escape(t.notes)}</p>`:''}</div></article>`;}
function sessionCard(a){return `<article class="session"><div class="session-time">${a.time}</div><div class="session-card ${a.category} ${a.done?'done':''}"><button class="session-title" data-action="edit-activity" data-id="${escape(a.id)}">${escape(a.title)}</button><div class="session-info"><span>${a.time}–${a.end}</span>${a.repeat==='weekly'?'<span>Каждую неделю</span>':''}</div>${a.location?`<p class="notes">${escape(a.location)}</p>`:''}${a.notes?`<p class="notes">${escape(a.notes)}</p>`:''}<div class="session-info"><button data-action="toggle-activity" data-id="${escape(a.id)}" data-date="${a.occurrenceDate}">${a.done?'Посещено · отменить отметку':'Отметить посещение'}</button></div></div></article>`;}
function empty(title,text,type){return `<div class="empty"><h3>${title}</h3><p>${text}</p><button class="primary" data-action="add-${type}">${icon('plus')} ${type==='task'?'Добавить дело':'Добавить занятие'}</button></div>`;}
function taskList(tasks){const active=tasks.filter(t=>!t.done),done=tasks.filter(t=>t.done);return `<div class="task-list">${active.map(taskCard).join('')||empty('Можно выдохнуть','Добавь домашнее задание или дело, которое важно успеть.','task')}</div>${done.length?`<h3 class="completed-heading">Выполнено · ${done.length}</h3><div class="task-list">${done.map(taskCard).join('')}</div>`:''}`;}
function summary(){const ts=data.tasks.filter(t=>t.date===selected),done=ts.filter(t=>t.done).length,mins=ts.filter(t=>!t.done).reduce((s,t)=>s+t.duration,0);return `<div class="summary"><div class="eyebrow">Маленькими шагами</div><strong>${done} из ${ts.length}</strong><p>дел выполнено на этот день</p><div class="progress"><div style="width:${ts.length?done/ts.length*100:0}%"></div></div><p>${mins?'На оставшиеся дела: '+(mins>=60?`${Math.floor(mins/60)} ч `:'')+(mins%60?`${mins%60} мин`:''):'В плане есть место для отдыха.'}</p></div>`;}
function todayPage(){const ts=data.tasks.filter(t=>t.date===selected||(!t.done&&t.date<selected)).sort((a,b)=>a.date.localeCompare(b.date)||(a.time||'99').localeCompare(b.time||'99')),events=occurrences(data,selected);return `${weekbar()}<div class="columns"><section><div class="section-head"><h2>Что нужно сделать <span class="count">${ts.filter(t=>!t.done).length}</span></h2><button data-action="add-task">+ Добавить</button></div>${taskList(ts)}</section><aside><div class="section-head"><h2>После школы</h2><button data-action="add-activity" aria-label="Добавить занятие">${icon('plus')}</button></div><div class="agenda">${events.map(sessionCard).join('')||empty('Пока без занятий','Запиши секцию, кружок или встречу с репетитором.','activity')}</div>${summary()}</aside></div>`;}
function tasksPage(){const now=dateKey(),end=addDays(weekStart(now),6);const ts=data.tasks.filter(t=>(filter==='all'||(filter==='today'&&t.date===now)||(filter==='week'&&t.date>=weekStart(now)&&t.date<=end)||(filter==='overdue'&&!t.done&&t.date<now))&&`${t.title} ${t.notes}`.toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru'))).sort((a,b)=>a.date.localeCompare(b.date)||(a.time||'99').localeCompare(b.time||'99'));return `<div class="filters">${[['all','Все дела'],['today','Сегодня'],['week','Эта неделя'],['overdue','Просрочено']].map(([v,l])=>`<button data-action="filter" data-value="${v}" class="${filter===v?'selected':''}" aria-pressed="${filter===v}">${l}</button>`).join('')}<input class="search" id="search" type="search" placeholder="Найти дело" aria-label="Найти дело" value="${escape(query)}"></div><div id="task-results">${ts.length?taskList(ts):'<div class="empty"><h3>Ничего не найдено</h3><p>Попробуй другой фильтр или добавь новое дело.</p><button class="primary" data-action="add-task">Добавить дело</button></div>'}</div>`;}
function schedulePage(){const start=weekStart(selected);return `${weekbar()}<div class="section-head"><h2>Занятия на неделю</h2><button class="secondary" data-action="export-calendar">Экспорт в календарь</button></div><div class="schedule-grid">${Array.from({length:7},(_,i)=>{const d=addDays(start,i),es=occurrences(data,d);return `<section class="schedule-day"><h2>${fmt(d,{weekday:'long'})} <span class="muted">${fmt(d,{day:'numeric',month:'short'})}</span></h2>${es.map(sessionCard).join('')||'<p class="day-empty">Свободный день</p>'}<button data-action="add-activity" data-date="${d}" class="small">+ Занятие</button></section>`;}).join('')}</div>`;}
function settingsPage(){return `<div class="settings"><section class="settings-card"><h2>Напоминания</h2><p>За 15 минут до дела или занятия появится сообщение в приложении. Включи системные уведомления, чтобы видеть их в других вкладках. Приложение должно оставаться открытым; доставка в фоне зависит от браузера.</p><label class="toggle"><input id="reminders" type="checkbox" ${data.settings.reminders?'checked':''}> Напоминать о планах</label><button class="secondary" data-action="notifications">Разрешить уведомления браузера</button></section><section class="settings-card"><h2>Твои данные</h2><p>Планы сохраняются в этом браузере на этом устройстве. Вход и синхронизация между устройствами в эту версию не входят. Скачивай резервную копию перед очисткой браузера.</p><button class="primary" data-action="export">Скачать копию</button><button class="secondary" data-action="import">Загрузить копию</button><button class="secondary" data-action="export-calendar">Экспорт в календарь</button><input type="file" id="import-file" accept="application/json,.json" hidden><p class="small">Копия: все дела и занятия в JSON. Календарь: занятия и незавершённые дела в ICS, без привязки к часовому поясу. Приложения календаря могут по-разному поддерживать список дел.</p></section><section class="settings-card"><h2>Начать с примера</h2><p>Посмотри, как выглядит неделя с баскетболом, репетитором и домашними заданиями. Пример добавляется только в пустой план.</p><button class="secondary" data-action="demo" ${data.tasks.length||data.activities.length?'disabled':''}>Добавить пример расписания</button></section></div>`;}
function render(){const headings={today:[selected===dateKey()?'Всё по плану.':pretty(selected),'Здесь занятия, домашние задания и время на себя.'],tasks:['Дела без спешки.','Запиши, что нужно сделать, и освободи голову.'],schedule:['У каждой встречи своё время.','Кружки, секции и репетиторы на одной неделе.'],settings:['Как тебе удобно.','Напоминания и резервные копии твоего плана.']};$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="./favicon.svg" alt=""> <div>После уроков<small>Время для своего</small></div></div><nav class="nav" aria-label="Основная навигация">${[['today','sun','Мой день'],['schedule','calendar','Расписание'],['tasks','list','Мои дела'],['settings','settings','Настройки']].map(([v,i,l])=>`<button data-action="view" data-value="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}${l}</button>`).join('')}</nav><div class="side-note"><div class="leaf">${icon('book')}</div><strong>После уроков тоже жизнь.</strong><p>Оставь в расписании место для того, что тебе нравится.</p></div></aside><main class="workspace"><header class="topbar"><span class="eyebrow">Твой личный план</span><div class="top-actions"><button class="icon-btn" data-action="view" data-value="settings" aria-label="Настройки напоминаний">${icon('bell')}</button><button class="primary" data-action="add-task">${icon('plus')} Добавить дело</button></div></header><div class="intro"><div><h1>${headings[view][0]}</h1><p>${headings[view][1]}</p></div><span class="date-label">${fmt(dateKey(),{weekday:'long'})}<br>${pretty(dateKey())}</span></div>${loadError?`<div class="warning">${escape(loadError)}</div>`:''}${data.tasks.some(t=>t.id.startsWith('demo-'))||data.activities.some(a=>a.id.startsWith('demo-'))?'<div class="banner"><span>Это пример расписания. Его можно редактировать или убрать целиком.</span><button data-action="remove-demo">Убрать пример</button></div>':''}${view==='today'?todayPage():view==='tasks'?tasksPage():view==='schedule'?schedulePage():settingsPage()}${!data.tasks.length&&!data.activities.length&&view==='today'?'<div class="empty-start"><button class="secondary" data-action="demo">Посмотреть на примере</button></div>':''}<p class="footer-note">${icon('shield')} ${loadError?'Есть проблема с сохранёнными данными. Открой настройки.':'Планы хранятся в этом браузере. Резервная копия доступна в настройках.'}</p></main></div>`;}
function closeModal(){const dialog=$('#editor');dialog.close();dialog.innerHTML='';modalReturn?.focus();}
function showModal(content){modalReturn=document.activeElement;$('#editor').innerHTML=content;$('#editor').showModal();}
function confirmModal(title,text,onConfirm,label='Продолжить'){showModal(`<div class="modal-head"><h2>${title}</h2><button data-action="close" aria-label="Закрыть">${icon('close')}</button></div><p class="long">${escape(text)}</p><div class="modal-actions"><button class="secondary" data-action="close">Отмена</button><button class="primary" id="confirm">${label}</button></div>`);$('#confirm').onclick=()=>{if(onConfirm()!==false)closeModal();};}
function editor(type,id,date){const activity=type==='activity',item=id?(activity?data.activities:data.tasks).find(x=>x.id===id):null;if(id&&!item)return;const x=item||{title:'',date:date||selected,time:activity?'16:00':'',end:'17:00',duration:30,category:activity?'club':'school',notes:'',location:'',repeat:'weekly'};showModal(`<div class="modal-head"><h2>${item?'Изменить':activity?'Новое занятие':'Новое дело'}</h2><button data-action="close" aria-label="Закрыть">${icon('close')}</button></div><form id="entry-form"><div class="form-grid"><label class="field full">${activity?'Название занятия':'Что нужно сделать'}<input name="title" maxlength="120" required value="${escape(x.title)}" placeholder="${activity?'Например, тренировка по волейболу':'Например, подготовиться к контрольной'}" autofocus></label><label class="field full">Категория<select name="category">${Object.entries(categories).map(([v,l])=>`<option value="${v}" ${v===x.category?'selected':''}>${l}</option>`).join('')}</select></label><label class="field full">${activity?'Дата первого занятия':'Дата дела'}<input type="date" name="date" min="2000-01-01" max="2100-12-31" value="${x.date}" required></label><label class="field half">${activity?'Начало':'Время (необязательно)'}<input type="time" name="time" value="${x.time}" ${activity?'required':''}></label>${activity?`<label class="field half">Окончание<input type="time" name="end" value="${x.end}" required></label><label class="field full">Повтор<select name="repeat"><option value="none" ${x.repeat==='none'?'selected':''}>Один раз</option><option value="weekly" ${x.repeat==='weekly'?'selected':''}>Каждую неделю</option></select></label><label class="field full">Место или ссылка<input name="location" maxlength="160" value="${escape(x.location)}" placeholder="Например, спортзал школы"></label>`:`<label class="field half">Сколько минут нужно<input type="number" min="5" max="480" step="5" name="duration" value="${x.duration}" required></label>`}<label class="field full">${activity?'Что взять или подготовить':'Заметка'}<textarea name="notes" maxlength="2000" placeholder="${activity?'Форма, вода, выполненное задание':'Подробности, которые пригодятся'}">${escape(x.notes)}</textarea></label></div>${activity&&item?.repeat==='weekly'?'<p class="form-hint">Изменения применятся ко всей серии занятий. Отметки посещения сохраняются по датам.</p>':''}<div id="form-message" role="alert"></div><div class="modal-actions">${item?'<button type="button" class="danger" id="archive-entry">Убрать '+(activity&&item.repeat==='weekly'?'всю серию':'из плана')+'</button>':''}<button type="button" class="secondary" data-action="close">Отмена</button><button type="submit" class="primary">Сохранить</button></div></form>`);
$('#entry-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),title=f.title.trim();if(!title){$('#form-message').innerHTML='<p class="form-error">Напиши название.</p>';return;}if(activity&&f.end<=f.time){$('#form-message').innerHTML='<p class="form-error">Окончание должно быть позже начала в тот же день.</p>';return;}const entry={...f,title,id:item?.id||crypto.randomUUID(),...(activity?{}:{duration:Number(f.duration),done:item?.done||false})};if(activity){const hits=conflicts(data,entry);if(hits.length&&!$('#allow-conflict')?.checked){$('#form-message').innerHTML=`<div class="warning">Занятие пересекается: ${hits.map(a=>escape(a.title)).join(', ')}.<label class="toggle"><input id="allow-conflict" type="checkbox"> Всё равно сохранить</label></div>`;return;}}if(update(d=>{const list=activity?d.activities:d.tasks,idx=list.findIndex(t=>t.id===entry.id);if(idx>=0)list[idx]=entry;else list.push(entry);})){closeModal();toast('Сохранено');}};
if(item)$('#archive-entry').onclick=()=>confirmModal('Убрать из плана?',activity&&item.repeat==='weekly'?'Все повторения этого занятия будут убраны. Сначала можно сохранить копию в настройках.':'Запись будет убрана из плана. Сначала можно сохранить копию в настройках.',()=>{const ok=update(d=>{if(activity){d.activities=d.activities.filter(a=>a.id!==item.id);d.completed=d.completed.filter(k=>!k.startsWith(item.id+'@'));}else d.tasks=d.tasks.filter(t=>t.id!==item.id);});if(ok)toast('Запись убрана');return ok;},'Убрать');}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id,value,date}=b.dataset;if(action==='view'){view=value;render();}if(action==='date'){selected=date;render();}if(action==='prev'||action==='next'){const next=addDays(selected,action==='prev'?-7:7);if(next>='2000-01-01'&&next<='2100-12-25'){selected=next;render();}}if(action==='today'){selected=dateKey();render();}if(action==='add-task')editor('task',null,date);if(action==='add-activity')editor('activity',null,date);if(action==='edit-task')editor('task',id);if(action==='edit-activity')editor('activity',id);if(action==='toggle-task')update(d=>{const t=d.tasks.find(t=>t.id===id);if(t)t.done=!t.done;});if(action==='toggle-activity')update(d=>{const key=`${id}@${date}`;d.completed=d.completed.includes(key)?d.completed.filter(x=>x!==key):[...d.completed,key];});if(action==='filter'){filter=value;render();}if(action==='close')closeModal();if(action==='demo'&&!data.tasks.length&&!data.activities.length){commit(demoData(dateKey()));toast('Пример добавлен. Все записи можно менять.');}if(action==='remove-demo')confirmModal('Убрать пример?', 'Будут убраны только записи примера. Созданные тобой дела и занятия останутся.',()=>update(d=>{d.tasks=d.tasks.filter(t=>!t.id.startsWith('demo-'));d.activities=d.activities.filter(t=>!t.id.startsWith('demo-'));d.completed=d.completed.filter(k=>!k.startsWith('demo-'));}),'Убрать пример');if(action==='export')download(JSON.stringify(data,null,2),`posle-urokov-${dateKey()}.json`,'application/json');if(action==='export-calendar'){if(!data.tasks.length&&!data.activities.length){toast('Сначала добавь дело или занятие');return;}download(calendarExport(data),'posle-urokov.ics','text/calendar;charset=utf-8');}if(action==='import')$('#import-file').click();if(action==='notifications')requestNotifications();});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
document.addEventListener('change',async e=>{if(e.target.id==='reminders')update(d=>d.settings.reminders=e.target.checked);if(e.target.id==='import-file'){const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>2*1024*1024){toast('Файл слишком большой. Максимум 2 МБ.');return;}try{const imported=validateData(JSON.parse(await file.text()));confirmModal('Загрузить копию?',`В копии: дел ${imported.tasks.length}, занятий ${imported.activities.length}. Текущий план будет заменён. Перед заменой автоматически скачается его резервная копия.`,()=>{download(JSON.stringify(data,null,2),`posle-urokov-before-import-${Date.now()}.json`,'application/json');const ok=commit(imported);if(ok){loadError='';render();toast('Копия загружена');}return ok;},'Загрузить');}catch(err){toast('Копия не загружена: '+err.message);}}});
$('#editor').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
async function requestNotifications(){if(!('Notification'in window)){toast('Браузер не поддерживает уведомления. Сообщения внутри приложения доступны.');return;}try{const permission=await Notification.requestPermission();if(permission==='granted'){update(d=>d.settings.reminders=true);toast('Уведомления включены, пока приложение открыто.');}else toast('Уведомления не разрешены. Можно включить их в настройках браузера.');}catch{toast('Не удалось включить уведомления в этом браузере.');}}
const notified=new Set();function checkReminders(){if(!data.settings.reminders)return;for(const item of dueReminders(data,new Date())){if(notified.has(item.key))continue;notified.add(item.key);toast(`Скоро: ${item.title} в ${item.time}`);if('Notification'in window&&Notification.permission==='granted'){try{new Notification('После уроков',{body:`${item.title} · ${item.time}`,tag:item.key});}catch{/* In-app reminder still works on browsers requiring a service worker. */}}}}
window.addEventListener('storage',e=>{if(e.key===STORAGE){try{data=e.newValue?validateData(JSON.parse(e.newValue)):emptyData();if($('#editor').open){closeModal();toast('План изменился в другой вкладке. Открой запись заново.');}render();}catch{toast('Не удалось прочитать изменения из другой вкладки.');}}});
setInterval(checkReminders,15000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){render();checkReminders();}});render();checkReminders();
